const fs = require('fs');
const path = require('path');

const configPath = path.join(__dirname, '..', 'js', 'config.js');
const supabaseUrl = process.env.SUPABASE_URL || 'YOUR_SUPABASE_PROJECT_URL';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || 'YOUR_SUPABASE_ANON_KEY';
const storageBucket = process.env.STORAGE_BUCKET || 'report-images';

const generatedConfig = `// ============================================
//  FootpathFix — Supabase Configuration
//  Generated during deploy from Vercel environment variables.
//  Do not edit this file manually unless you are running locally.
// ============================================

const SUPABASE_URL     = ${JSON.stringify(supabaseUrl)};
const SUPABASE_ANON_KEY = ${JSON.stringify(supabaseAnonKey)};

// Storage bucket name (create this in Supabase > Storage)
const STORAGE_BUCKET   = ${JSON.stringify(storageBucket)};

// App config
const APP_CONFIG = {
  maxFileSizeMB:     5,
  allowedImageTypes: ['image/jpeg', 'image/png', 'image/webp'],
  itemsPerPage:      12,
};
`;

fs.writeFileSync(configPath, generatedConfig, 'utf8');
console.log(`Generated ${configPath} using Supabase config from environment variables.`);
